<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { Head, Link } from '@inertiajs/vue3';
type SaleItem={id:number;product_name:string;product_slug:string;variant_name:string|null;sku:string|null;regular_price:string|number;sale_price:string|number;quantity_remaining:number|null};
type Sale={id:number;title:string;slug:string;tagline:string|null;description:string|null;banner_image:string|null;accent_color:string;starts_at:string;ends_at:string;items:SaleItem[]};
const sales=ref<Sale[]>([]),loading=ref(true),error=ref('');
async function load(){try{const r=await fetch('/api/v1/storefront/flash-sales',{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('Flash sales are temporarily unavailable.');const p=await r.json();sales.value=p.data??[];}catch(e){error.value=e instanceof Error?e.message:'Unable to load flash sales.';}finally{loading.value=false;}}
function money(v:string|number){return new Intl.NumberFormat('en-BD',{style:'currency',currency:'BDT',maximumFractionDigits:2}).format(Number(v)||0)}
function discount(a:string|number,b:string|number){const regular=Number(a),sale=Number(b);return regular>0?Math.max(0,Math.round((regular-sale)/regular*100)):0}
onMounted(load);
</script>
