<Head title="Flash Sales | Madina Scale"/>
<main class="flash-store">
  <header class="store-head"><Link href="/" class="brand"><span>MS</span><strong>MADINA SCALE</strong></Link><nav><Link href="/products">Shop</Link><Link href="/shop/flash-sales" class="current">Flash sales</Link></nav><Link href="/products" class="back">Explore products ↗</Link></header>
  <section class="hero"><div class="hero-copy"><span class="eyebrow">LIMITED TIME · LIMITED STOCK</span><h1>Flash sales<span>.</span></h1><p>Exceptional offers on selected products. When the timer ends, these prices are gone.</p><div class="hero-pills"><span>✦ Curated deals</span><span>◷ Time-limited</span><span>↗ Live availability</span></div></div><div class="hero-art"><div class="orb orb-one"></div><div class="orb orb-two"></div><div class="flash-mark">FLASH<br/><b>SALE</b><span>LIVE DEALS</span></div></div></section>
  <section class="deals"><div class="section-head"><div><span class="eyebrow">THE DROP</span><h2>Live campaigns</h2><p>Campaign availability is scheduled by Madina Scale.</p></div><span class="live-pill"><i></i> LIVE OFFERS</span></div>
  <div v-if="loading" class="state">Finding live deals…</div><div v-else-if="error" class="state error">{{error}}</div><div v-else-if="!sales.length" class="state"><strong>No live flash sales right now</strong><p>Check back soon for the next drop.</p><Link href="/products" class="cta">Browse the shop</Link></div>
  <article v-for="sale in sales" :key="sale.id" class="campaign" :style="{'--accent':sale.accent_color}"><div v-if="sale.banner_image" class="campaign-banner" :style="{backgroundImage:`linear-gradient(90deg,#071b18e8,#071b1840),url('${sale.banner_image}')`}"><span class="live-pill"><i></i> LIVE NOW</span><h3>{{sale.title}}</h3><p>{{sale.tagline||sale.description}}</p></div><div v-else class="campaign-banner no-image"><span class="live-pill"><i></i> LIVE NOW</span><h3>{{sale.title}}</h3><p>{{sale.tagline||sale.description||'A limited-time selection at special prices.'}}</p><span class="banner-watermark">FLASH</span></div><div class="product-grid"><article v-for="item in sale.items" :key="item.id" class="product"><div class="product-top"><span class="deal-badge">−{{discount(item.regular_price,item.sale_price)}}%</span><span v-if="item.quantity_remaining!==null" class="stock">{{item.quantity_remaining>0?`${item.quantity_remaining} left`:'Sold out'}}</span></div><div class="product-icon">✦</div><h4>{{item.product_name}}</h4><p class="variant">{{item.variant_name||item.sku||'Selected variant'}}</p><div class="prices"><strong>{{money(item.sale_price)}}</strong><del>{{money(item.regular_price)}}</del></div><Link :href="`/products/${item.product_slug}`" class="product-link">View product <span>↗</span></Link></article></div></article>
  </section><footer><span>© Madina Scale</span><span>Offers are subject to availability and campaign terms.</span><Link href="/products">Return to shop</Link></footer>
</main>
